const { chromium } = require('playwright');
const fuente = '<title>Envío 4821</title>\n<h1>Seguimiento</h1>\n<p>Estado: en ruta\n<a href="/historial">Historial</a>';
function mostrar(n, nivel, out) {
  const pad = '  '.repeat(nivel);
  if (n.nodeType === 3) {
    out.push(pad + '#texto «' + n.textContent.replace(/\n/g, '⏎') + '»');
  } else {
    const attrs = [...(n.attributes || [])].map(a => ' ' + a.name + '="' + a.value + '"').join('');
    out.push(pad + '<' + n.nodeName.toLowerCase() + attrs + '>');
    n.childNodes.forEach(h => mostrar(h, nivel + 1, out));
  }
}
(async () => {
  const b = await chromium.launch();
  const pg = await b.newPage();
  await pg.setContent(fuente);
  const lineas = await pg.evaluate(`(${mostrar.toString()})(document.documentElement, 0, window.__o = []) || window.__o`);
  console.log(lineas.join('\n'));
  await b.close();
})();
